&lt;li value=&quot;1&quot;&gt;&lt;a href=&quot;https://about.gitlab.com/handbook/total-rewards/benefits/general-and-entity-benefits/&quot;&gt;Benefits to support your health, finances, and well-being&lt;/a&gt;&lt;/li&gt;
&lt;li value=&quot;2&quot;&gt;&lt;a href=&quot;https://about.gitlab.com/company/culture/all-remote/asynchronous/&quot;&gt;All remote, asynchronous work environment&lt;/a&gt;&lt;/li&gt;
&lt;li value=&quot;3&quot;&gt;&lt;a href=&quot;https://about.gitlab.com/handbook/paid-time-off/&quot;&gt;Flexible Paid Time Off&lt;/a&gt;&lt;/li&gt;
&lt;li value=&quot;4&quot;&gt;&lt;a href=&quot;https://about.gitlab.com/company/culture/inclusion/erg-guide/&quot;&gt;Team Member Resource Groups&lt;/a&gt;&lt;/li&gt;
&lt;li value=&quot;5&quot;&gt;&lt;a href=&quot;https://handbook.gitlab.com/handbook/total-rewards/stock-options/&quot;&gt;Equity Compensation&lt;/a&gt; and &lt;a href=&quot;https://handbook.gitlab.com/handbook/total-rewards/stock-options/#employee-stock-purchase-plan-espp&quot;&gt;Employee Stock Purchase Plan&lt;/a&gt;&lt;/li&gt;
